<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { session } from '../session'
import { getPlanContextWords, savePlanContextWords, organizePlanContextWords, type ContextWord, type ContextWordCatalog } from '../api'
const props=defineProps<{planId:number}>()
type Draft=ContextWord&{localKey:string}
const catalog=ref<ContextWordCatalog>({revision:0,items:[]}),draft=ref<Draft[]>([]),raw=ref(''),questions=ref<string[]>([]),search=ref(''),error=ref(''),notice=ref(''),busy=ref(false),loaded=ref(false),editing=ref(''),selected=ref<string[]>([])
const triggerText=ref(''),meaning=ref(''),whenText=ref(''),example=ref('')
const actor=computed(()=>`${session.bootstrap?.actor?.tenant_id||0}:${session.bootstrap?.actor?.user_id||0}`)
const storageKey=computed(()=>`context-words:v1:${actor.value}:${props.planId}`)
let epoch=0
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v))
const visible=computed(()=>catalog.value.items.filter(e=>`${e.triggers.join(' ')} ${e.meaning} ${e.when||''} ${e.example||''}`.includes(search.value.trim())))
function persist(){if(!loaded.value)return;try{localStorage.setItem(storageKey.value,JSON.stringify({raw:raw.value,draft:draft.value,questions:questions.value}))}catch{error.value='浏览器未能保存未确认内容，请暂时保留原文。'}}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';const token=epoch;try{await fn()}catch(e){if(token===epoch)error.value=e instanceof Error?e.message:'操作失败，请重试'}finally{if(token===epoch)busy.value=false}}
async function load(){const token=epoch;try{const out=await getPlanContextWords(props.planId);if(token!==epoch)return;catalog.value=out;loaded.value=true;error.value=''}catch(e){if(token===epoch)error.value=e instanceof Error?e.message:'读取失败'}}
function makeDraft(e:ContextWord):Draft{return {...clone(e),id:undefined,enabled:true,localKey:crypto.randomUUID()}}
function triggers(value:string){return [...new Set(value.split(/[、,，|\n]/).map(s=>s.trim()).filter(Boolean))]}
function valid(e:ContextWord){if(!e.triggers.length||e.triggers.length>20||e.triggers.some(t=>[...t].length>80)||!e.meaning.trim()||[...e.meaning].length>400||[...(e.when||'')].length>300||[...(e.example||'')].length>200)throw Error('请填写触发词和含义，并检查各项长度。')}
function resetForm(){editing.value='';triggerText.value='';meaning.value='';whenText.value='';example.value=''}
function editEntry(e:ContextWord){editing.value=e.id||'';triggerText.value=e.triggers.join('、');meaning.value=e.meaning;whenText.value=e.when||'';example.value=e.example||''}
function formEntry():ContextWord{const e={triggers:triggers(triggerText.value),meaning:meaning.value.trim(),when:whenText.value.trim(),example:example.value.trim(),enabled:true};valid(e);return e}
async function saveCatalog(items:ContextWord[]){const token=epoch;const out=await savePlanContextWords(props.planId,{revision:catalog.value.revision,items});if(token!==epoch)return false;catalog.value=out;return true}
async function saveForm(){await run(async()=>{const e=formEntry();if(editing.value){const id=editing.value,old=catalog.value.items.find(x=>x.id===id);if(!old)throw Error('条目已变化，请刷新');if(await saveCatalog(catalog.value.items.map(x=>x.id===id?{...e,id,enabled:x.enabled}:x))){resetForm();notice.value='修改已保存。'}}else{draft.value.push(makeDraft(e));selected.value.push(draft.value.at(-1)!.localKey);resetForm();persist();notice.value='已加入待确认，核对后点击“确认保存”。'}})}
function readLines(){error.value='';notice.value='';const lines=raw.value.split('\n').map(x=>x.trim()).filter(Boolean);try{if(!lines.length||lines.length>50)throw Error('请一次粘贴1至50行');const rows=lines.map(line=>{const m=line.match(/^(.+?)\s*[=＝→]\s*(.+)$/);if(!m)throw Error('每行使用“触发词 = 含义”；大白话描述请点击“大白话整理”。');const e={triggers:triggers(m[1]!),meaning:m[2]!.trim(),enabled:true};valid(e);return makeDraft(e)});draft.value=rows;selected.value=rows.map(e=>e.localKey);questions.value=[];persist();notice.value=`已读取 ${rows.length} 条，核对后确认保存。`}catch(e){error.value=(e as Error).message}}
async function organize(){await run(async()=>{const token=epoch,out=await organizePlanContextWords(props.planId,raw.value);if(token!==epoch)return;draft.value=out.items.map(makeDraft);selected.value=draft.value.map(e=>e.localKey);questions.value=out.questions||[];persist();notice.value='整理完成，核对含义与条件后确认保存。'})}
async function confirmDraft(){await run(async()=>{const rows=draft.value.filter(e=>selected.value.includes(e.localKey));if(!rows.length)throw Error('请勾选要保存的语境词');rows.forEach(valid);const entries=rows.map(({localKey,...e})=>e);if(await saveCatalog([...catalog.value.items,...entries])){const keys=new Set(rows.map(e=>e.localKey));draft.value=draft.value.filter(e=>!keys.has(e.localKey));selected.value=[];persist();notice.value=`已保存 ${rows.length} 条，后续问题命中时会提供给模型理解。`}})}
async function toggle(e:ContextWord){await run(async()=>{if(await saveCatalog(catalog.value.items.map(x=>x.id===e.id?{...x,enabled:!x.enabled}:x)))notice.value=e.enabled?'已停用。':'已启用。'})}
async function remove(e:ContextWord){if(!confirm('删除这条语境词？'))return;await run(async()=>{if(await saveCatalog(catalog.value.items.filter(x=>x.id!==e.id))){if(editing.value===e.id)resetForm();notice.value='已删除。'}})}
watch([()=>props.planId,actor],()=>{epoch++;busy.value=false;loaded.value=false;catalog.value={revision:0,items:[]};draft.value=[];raw.value='';questions.value=[];error.value='';notice.value='';selected.value=[];resetForm();try{const saved=JSON.parse(localStorage.getItem(storageKey.value)||'null');if(saved){raw.value=String(saved.raw||'');draft.value=Array.isArray(saved.draft)?saved.draft:[];questions.value=Array.isArray(saved.questions)?saved.questions:[]}}catch{error.value='未确认内容恢复失败，请重新粘贴。'}void load()},{immediate:true})
watch([raw,draft,questions],persist,{deep:true})
</script>

<template>
<section class="context-words">
 <header><div><h2>语境词</h2><p>把同义词、别名和容易误解的说法放在一起。命中问题后，帮助模型结合语境理解。</p></div><button :disabled="busy" @click="load">刷新</button></header>
 <p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status" class="notice">{{notice}}</p>
 <div class="entry-grid">
  <section class="panel"><h3>粘贴或描述</h3><p>可每行写“切 = 切块”，也可描述“谈商品处理时，切就是切块；谈价格时砍指还价”。</p><label for="context-word-raw">词义说明</label><textarea id="context-word-raw" v-model="raw" :disabled="busy" maxlength="8000" placeholder="触发词 = 含义，或直接用大白话描述"/><div class="actions"><button :disabled="busy||!loaded||!raw.trim()" @click="readLines">按行读取</button><button class="primary" :disabled="busy||!loaded||!raw.trim()" @click="organize">{{busy?'处理中…':'大白话整理'}}</button></div></section>
  <section class="panel"><h3>{{editing?'修改语境词':'手工填写'}}</h3><label>触发词<input v-model="triggerText" :disabled="busy" placeholder="多个词用顿号分隔，如：寄、邮、发货"/></label><label>理解为<textarea v-model="meaning" :disabled="busy" rows="2" maxlength="400" placeholder="说明这些词在本业务里是什么意思"/></label><div class="optional"><label>适用条件<input v-model="whenText" :disabled="busy" maxlength="300" placeholder="如：讨论商品处理时"/></label><label>例句<input v-model="example" :disabled="busy" maxlength="200" placeholder="如：能切吗、切一下"/></label></div><div class="actions"><button class="primary" :disabled="busy||!loaded" @click="saveForm">{{editing?'保存修改':'加入待确认'}}</button><button v-if="editing" :disabled="busy" @click="resetForm">取消修改</button></div></section>
 </div>
 <section v-if="draft.length||questions.length" class="panel preview"><h3>待确认 {{draft.length}}</h3><p>可修改整理结果。确认保存后，才用于问题理解。</p><p v-for="q in questions" :key="q" class="question">待补充：{{q}}</p><article v-for="e in draft" :key="e.localKey" class="draft-row"><label class="pick"><input v-model="selected" type="checkbox" :value="e.localKey" :disabled="busy" :aria-label="'保存 '+e.triggers.join('、')"/>保存此条</label><label>触发词<input :value="e.triggers.join('、')" :disabled="busy" @change="e.triggers=triggers(($event.target as HTMLInputElement).value)"/></label><label>理解为<textarea v-model="e.meaning" rows="2" :disabled="busy" maxlength="400"/></label><div class="optional"><label>适用条件<input v-model="e.when" :disabled="busy" maxlength="300"/></label><label>例句<input v-model="e.example" :disabled="busy" maxlength="200"/></label></div></article><div class="actions"><button class="primary" :disabled="busy||!selected.length" @click="confirmDraft">确认保存</button></div></section>
 <section class="panel library"><div class="library-head"><h3>已保存 {{catalog.items.length}}</h3><input v-model="search" aria-label="搜索语境词" placeholder="搜索触发词、含义或条件"/></div><p v-if="!loaded">正在读取语境词，读取失败可点击刷新。</p><p v-else-if="!visible.length">{{catalog.items.length?'没有匹配的语境词。':'还没有语境词，可在上方填写或粘贴。'}}</p><article v-for="e in visible" :key="e.id" class="saved-row"><div><div class="terms"><b v-for="t in e.triggers" :key="t">{{t}}</b><span v-if="!e.enabled">已停用</span></div><p class="meaning">{{e.meaning}}</p><p v-if="e.when">适用条件：{{e.when}}</p><p v-if="e.example">例句：{{e.example}}</p></div><div class="actions"><button :disabled="busy" @click="editEntry(e)">修改</button><button :disabled="busy" @click="toggle(e)">{{e.enabled?'停用':'启用'}}</button><button class="danger" :disabled="busy" @click="remove(e)">删除</button></div></article></section>
</section>
</template>

<style scoped>
.context-words,.context-words *{box-sizing:border-box}.context-words{font-size:18px;color:#283552;min-width:0}.context-words h2{font-size:26px;margin:0 0 12px}.context-words h3{font-size:20px;margin:0 0 14px}.context-words p{font-size:18px;line-height:1.6;margin:8px 0 16px;color:#65728b;overflow-wrap:anywhere}.context-words header,.library-head{display:flex;align-items:flex-start;justify-content:space-between;gap:20px}.entry-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel{background:#fff;border:1px solid #e4e7f3;border-radius:18px;padding:24px;margin-bottom:20px;min-width:0}.context-words label{display:grid;gap:8px;font-size:18px;margin-bottom:14px}.context-words input:not([type=checkbox]),.context-words textarea{display:block;width:100%;min-width:0;max-width:100%;font:inherit;font-size:18px;line-height:1.5;color:#283552;border:1px solid #dfe4f2;border-radius:12px;padding:12px 14px;background:#fcfcff;height:auto}.context-words textarea{resize:vertical;min-height:76px}#context-word-raw{min-height:260px}.context-words button{width:auto;font:inherit;font-size:18px;min-height:46px;border:1px solid #e0e4f1;border-radius:12px;padding:10px 16px;background:#fff;color:#3b4966;cursor:pointer}.context-words button.primary{background:#704bff;border-color:#704bff;color:#fff}.context-words button:disabled{opacity:.5;cursor:default}.context-words button.danger,.context-words .error{color:#c9343b}.context-words .error{background:#fff1f1;padding:14px;border-radius:12px}.context-words .notice{color:#278168}.actions{display:flex;flex-wrap:wrap;gap:10px}.optional{display:grid;grid-template-columns:1fr 1fr;gap:14px}.draft-row{border-top:1px solid #e9ecf5;padding-top:20px;margin-top:20px}.context-words .pick{display:flex;align-items:center;gap:10px}.context-words input[type=checkbox]{appearance:auto;width:18px!important;height:18px!important;min-width:18px;margin:0;accent-color:#704bff}.library-head input{flex:0 1 460px}.saved-row{display:flex;justify-content:space-between;gap:24px;padding:22px 0;border-top:1px solid #ebedf6}.saved-row>div:first-child{min-width:0}.saved-row .actions{align-content:flex-start;flex-shrink:0}.terms{display:flex;flex-wrap:wrap;gap:8px}.terms b{padding:5px 10px;background:#f1edff;color:#6849de;border-radius:8px;font-weight:600}.saved-row .meaning{color:#283552;white-space:pre-wrap}.context-words .question{color:#94631d}@media(max-width:850px){.entry-grid{grid-template-columns:1fr}.saved-row{display:block}.optional{grid-template-columns:1fr;gap:0}.panel{padding:18px}.library-head{flex-wrap:wrap}.library-head input{flex-basis:100%}.context-words header{flex-wrap:wrap}}
</style>
